import { useEffect, useState } from "react";
import { motion } from "motion/react";

type Msg = {
  time: string;
  text: string;
  mine?: boolean;
};

const MESSAGES: Msg[] = [
  { time: "09:12", text: "Киа Рио, стук спереди справа", mine: true },
  { time: "09:14", text: "Приняли. Подъёмник 3, мастер Дмитрий", mine: false },
  { time: "10:40", text: "Диагностика: стойка стабилизатора и втулки. Запчасти в наличии", mine: false },
  { time: "11:05", text: "Согласуйте работы за 4 300 ₽", mine: false },
  { time: "11:07", text: "Да, делаем", mine: true },
  { time: "14:20", text: "Заменили. Фото деталей отправляю", mine: false },
];

const STAGES = ["Приём", "Диагностика", "Работы", "Контроль", "Выдача"];

export default function MasterChat() {
  const [visible, setVisible] = useState(1);

  useEffect(() => {
    if (typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setVisible(MESSAGES.length);
      return;
    }
    const t = setInterval(() => {
      setVisible((v) => (v >= MESSAGES.length ? 1 : v + 1));
    }, 1600);
    return () => clearInterval(t);
  }, []);

  const currentStage = STAGES[Math.min(3, Math.floor((visible / MESSAGES.length) * STAGES.length))];

  return (
    <section className="border-t border-line bg-background px-4 py-14 sm:py-20">
      <div className="mx-auto max-w-5xl">
        <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="font-mono text-xs text-muted-foreground">Химмаш, подъёмник 3</p>
            <h2 className="mt-2 max-w-md text-2xl font-semibold leading-tight text-foreground sm:text-3xl">
              Мастер пишет вам сам. Звонить не нужно
            </h2>
          </div>
          <p className="max-w-xs text-sm text-muted-foreground">
            Обычно за 1 день. Ремонт обычно занимает день — от приёмки до выдачи, все статусы в Telegram.
          </p>
        </div>

        <div className="grid gap-6 md:grid-cols-[1fr_240px]">
          {/* Телефон с чатом */}
          <div className="rounded-2xl border border-line bg-surface-alt p-4 sm:p-5">
            <div className="mb-4 flex items-center gap-3 border-b border-line pb-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary font-semibold text-primary-foreground">
                Д
              </div>
              <div>
                <p className="text-sm font-medium text-foreground">Дмитрий, мастер</p>
                <p className="text-xs text-muted-foreground">Сейчас на подъёмнике</p>
              </div>
              <span className="ml-auto rounded-full border border-line px-2 py-0.5 text-xs text-muted-foreground">
                Telegram
              </span>
            </div>

            <div className="flex h-72 flex-col justify-end gap-2 overflow-hidden sm:h-80">
              {MESSAGES.slice(0, visible).map((m, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.35 }}
                  className={`flex ${m.mine ? "justify-end" : "justify-start"}`}
                >
                  <div
                    className={`max-w-[78%] rounded-2xl px-3.5 py-2 text-sm leading-snug ${
                      m.mine
                        ? "rounded-br-md bg-primary text-primary-foreground"
                        : "rounded-bl-md border border-line bg-background text-foreground"
                    }`}
                  >
                    <p>{m.text}</p>
                    <p className={`mt-1 text-right font-mono text-[10px] ${m.mine ? "text-primary-foreground/70" : "text-muted-foreground"}`}>
                      {m.time}
                    </p>
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="mt-4 rounded-xl border border-line bg-background px-3 py-2.5 text-sm text-muted-foreground">
              Фото старых деталей получили. Готово к 17:00
            </div>
          </div>

          {/* Этапы */}
          <div className="rounded-2xl border border-line bg-background p-5">
            <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Заказ-наряд 2418</p>
            <ol className="mt-4 space-y-4">
              {STAGES.map((s, i) => {
                const done = STAGES.indexOf(currentStage) >= i;
                return (
                  <li key={s} className="flex items-center gap-3">
                    <span
                      className={`h-2.5 w-2.5 shrink-0 rounded-full border ${
                        done ? "border-primary bg-primary" : "border-line bg-background"
                      }`}
                    />
                    <span className={`text-sm ${done ? "text-foreground" : "text-muted-foreground"}`}>{s}</span>
                    {STAGES.indexOf(currentStage) === i && (
                      <span className="ml-auto font-mono text-[10px] text-accent-text">сейчас</span>
                    )}
                  </li>
                );
              })}
            </ol>
            <div className="mt-6 border-t border-line pt-4">
              <p className="text-sm text-foreground">4 300 ₽ согласованные работы</p>
              <p className="mt-1 text-xs text-muted-foreground">Гарантия 12 месяцев на работы</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

