args.source:
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

const CYCLES = [
  { time: "07:40", label: "Ленина 52 · первая закладка Эфиопии Гуджи" },
  { time: "11:20", label: "Колумбия Уила · конец первой обжарки" },
  { time: "16:05", label: "Бразилия Серрадо · закладка на неделю" },
];

export default function RoastClock() {
  const reduced = useReducedMotion();
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    if (reduced) return;
    const t = setInterval(() => setIdx((i) => (i + 1) % CYCLES.length), 3800);
    return () => clearInterval(t);
  }, [reduced]);

  const current = CYCLES[idx];

  return (
    <section className="bg-background px-5 py-14 sm:px-10">
      <div className="mx-auto max-w-5xl">
        <div className="border-y border-line py-2 text-[11px] uppercase tracking-[0.35em] text-foreground/60">
          Цех · Перми
        </div>

        <div className="relative mt-8 overflow-hidden border-b border-line pb-10">
          {/* Цифры поднимаются из-под края */}
          <div className="relative h-28 overflow-hidden sm:h-40">
            <motion.h2
              key={reduced ? "static" : current.time}
              initial={reduced ? false : { y: "110%" }}
              animate={{ y: 0 }}
              transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
              className="absolute inset-0 flex items-end text-[26vw] font-semibold leading-none tabular-nums tracking-tight text-foreground sm:text-[11rem]"
            >
              {current.time}
            </motion.h2>
          </div>

          {/* Строка проявляется следом */}
          <motion.p
            key={reduced ? "static" : current.label}
            initial={reduced ? false : { opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: reduced ? 0 : 0.55, duration: 0.6 }}
            className="mt-5 font-mono text-sm text-foreground/70 sm:text-base"
          >
            {current.label}
          </motion.p>
        </div>

        <div className="mt-8 grid gap-6 sm:grid-cols-3 sm:gap-10">
          <p className="text-sm leading-relaxed text-foreground/70">
            Печь работает каждую неделю: 6 сортов из Эфиопии, Колумбии и
            Бразилии. Дата обжарки напечатана на каждой пачке 250 г.
          </p>
          <p className="text-sm leading-relaxed text-foreground/70">
            Пачки из этой партии уезжают в три точки города к открытию
            в 7:30: Ленина 52, Монастырская 14, ТЦ Алмаз.
          </p>
          <p className="text-sm leading-relaxed text-foreground/70">
            За печью стоят бариста с сертификацией SCA. Спросите у стойки,
            что обжарено сегодня.
          </p>
        </div>
      </div>
    </section>
  );
}

