import { useEffect, useState } from "react";
import { m, LazyMotion, domAnimation, useReducedMotion } from "motion/react";

type Msg = {
  from: "master" | "client";
  text: string;
  time: string;
  photo?: boolean;
};

const MESSAGES: Msg[] = [
  { from: "master", text: "Авто на подъёмнике. Начинаю с диагностики ходовой.", time: "09:12" },
  { from: "client", text: "Хорошо, жду", time: "09:14" },
  { from: "master", text: "Нашёл люфт в переднем правом шаровом. Фото прикладываю.", time: "10:05", photo: true },
  { from: "master", text: "Замена шаровой и развал-сходимость — 4 300 ₽. Начинаю?", time: "10:06" },
  { from: "client", text: "Да, делайте", time: "10:09" },
  { from: "master", text: "Готово в 15:40. По гарантии на работу 12 месяцев.", time: "15:41" },
];

const STAGES = ["Приёмка", "Диагностика", "Согласование цены", "Ремонт", "Выдача"];

export default function MasterChat() {
  const [count, setCount] = useState(0);
  const reduce = useReducedMotion();

  useEffect(() => {
    if (reduce || count >= MESSAGES.length) return;
    const t = setTimeout(() => setCount((c) => c + 1), 1400);
    return () => clearTimeout(t);
  }, [count, reduce]);

  const visible = reduce ? MESSAGES.length : count;
  const stage = reduce ? 4 : visible < 1 ? -1 : visible < 3 ? 0 : visible < 4 ? 1 : visible < 5 ? 2 : visible < 6 ? 3 : 4;

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background py-16 md:py-24">
        <div className="mx-auto max-w-6xl px-4 md:px-8">
          <div className="mb-8 md:mb-12">
            <h2 className="font-semibold text-foreground text-2xl md:text-4xl tracking-tight">
              Ремонт без звонков: диалог с мастером в Telegram
            </h2>
            <p className="mt-3 text-muted-foreground text-sm md:text-base max-w-xl">
              312 отзывов на картах, средняя оценка 4,9. Переписка ниже повторяет структуру реального диалога из нашего сервиса, имена изменены.
            </p>
          </div>

          <div className="grid gap-6 md:grid-cols-5 md:gap-8">
            <div className="order-2 md:order-1 md:col-span-2">
              <div className="rounded-2xl border border-line bg-surface-alt p-5 md:p-6">
                <p className="text-xs uppercase tracking-widest text-muted-foreground mb-4">
                  Заказ №1428, сегодня
                </p>
                <ol className="space-y-3">
                  {STAGES.map((s, i) => {
                    const done = i < stage;
                    const active = i === stage;
                    return (
                      <li key={s} className="flex items-center gap-3">
                        <span
                          className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-xs font-medium ${
                            done || active
                              ? "border-primary bg-primary text-primary-foreground"
                              : "border-line text-muted-foreground"
                          }`}
                        >
                          {done ? "✓" : i + 1}
                        </span>
                        <span
                          className={`text-sm ${
                            done || active ? "text-foreground" : "text-muted-foreground"
                          }`}
                        >
                          {s}
                          {active && !reduce && (
                            <m.span
                              animate={{ opacity: [1, 0.3, 1] }}
                              transition={{ repeat: Infinity, duration: 1.6 }}
                              className="ml-2 inline-block h-2 w-2 rounded-full bg-primary"
                            />
                          )}
                        </span>
                      </li>
                    );
                  })}
                </ol>
                <div className="mt-5 border-t border-line pt-4 text-xs text-muted-foreground">
                  Гарантия 12 месяцев на работы, 6 месяцев на запчасти
                </div>
              </div>
            </div>

            <div className="order-1 md:order-2 md:col-span-3">
              <div className="rounded-2xl border border-line bg-surface-alt overflow-hidden">
                <div className="flex items-center gap-3 border-b border-line px-4 py-3">
                  <span className="flex h-9 w-9 items-center justify-center rounded-full bg-accent text-accent-ink text-xs font-semibold">
                    ИК
                  </span>
                  <div>
                    <p className="text-sm font-medium text-foreground">Игорь, мастер</p>
                    <p className="text-xs text-muted-foreground">Гараж 24 · Химмаш</p>
                  </div>
                </div>
                <div className="flex flex-col gap-2 p-4 min-h-[380px] md:min-h-[420px]">
                  {MESSAGES.slice(0, visible).map((msg, i) => (
                    <m.div
                      key={i}
                      initial={reduce ? false : { opacity: 0, y: 8 }}
                      animate={{ opacity: 1, y: 0 }}
                      className={`max-w-[82%] rounded-2xl px-4 py-2.5 text-sm ${
                        msg.from === "master"
                          ? "self-start bg-accent text-accent-ink rounded-bl-sm"
                          : "self-end bg-primary text-primary-foreground rounded-br-sm"
                      }`}
                    >
                      {msg.photo && (
                        <div className="mb-2 flex h-24 w-36 items-center justify-center rounded-lg border border-line bg-background text-xs text-muted-foreground">
                          фото: люфт шаровой опоры
                        </div>
                      )}
                      <p>{msg.text}</p>
                      <p className="mt-1 text-xs opacity-60 text-right">{msg.time}</p>
                    </m.div>
                  ))}
                  {visible < MESSAGES.length && !reduce && (
                    <span className="self-start rounded-2xl bg-accent px-4 py-3">
                      <m.span
                        animate={{ opacity: [0.2, 1, 0.2] }}
                        transition={{ repeat: Infinity, duration: 1.2 }}
                        className="inline-block h-1.5 w-1.5 rounded-full bg-accent-ink"
                      />
                    </span>
                  )}
                  {visible >= MESSAGES.length && (
                    <p className="mt-auto text-center text-xs text-muted-foreground">
                      Итог: 4 300 ₽, 6 часов в сервисе. Работаем с 8:00 до 23:00, без выходных.
                    </p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}


