                    className="max-w-[85%] self-start rounded-2xl rounded-bl-sm border border-line bg-background px-3 py-2"
                  >
                    <p className="text-sm leading-snug text-foreground">{msg.text}</p>
                    {msg.img && (
                      <div className="mt-2 flex h-24 items-center justify-center rounded-lg bg-accent text-xs font-medium text-accent-ink">
                        фото работ
                      </div>
                    )}
                  </m.div>
                ))}

                {typing && (
                  <div className="flex items-center gap-1.5 self-start rounded-2xl rounded-bl-sm border border-line bg-background px-3 py-2.5">
                    <m.span
                      animate={reduce ? undefined : { opacity: [0.2, 1, 0.2] }}
                      transition={{ duration: 1, repeat: Infinity }}
                      className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                    />
                    <m.span
                      animate={reduce ? undefined : { opacity: [0.2, 1, 0.2] }}
                      transition={{ duration: 1, repeat: Infinity, delay: 0.2 }}
                      className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                    />
                    <m.span
                      animate={reduce ? undefined : { opacity: [0.2, 1, 0.2] }}
                      transition={{ duration: 1, repeat: Infinity, delay: 0.4 }}
                      className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}
